record.field:
{"type":"object","properties":{
            "alert_id":{"type":"integer","description":"ID för saltstack.alert-recordet"},
            "bedömning":{"type":"string","description":"Diagnosbedömning / slutsats","default":""},
            "status":{"type":"string","description":"pending, running, done, error","default":""},
            "resolved":{"type":"boolean","description":"Markera löst","default":false},
            "åtgärdsplan":{"type":"string","description":"Åtgärdsplan att lägga i beskrivningen","default":""}
        },"required":["alert_id"]}

async def execute(alert_id, bedömning="", status="", resolved=False, åtgärdsplan=""):
    """Uppdatera Driftlarm-record med bedömning och status."""
    if "saltstack.alert" not in env:
        return "ERROR: saltstack.alert-modellen finns inte"
    alert = env["saltstack.alert"].browse(alert_id)
    if not alert.exists():
        return f"ERROR: Driftlarm {alert_id} finns inte"
    vals = {}
    if bedömning:
        vals["diagnosis_result"] = bedömning
    if status:
        vals["diagnosis_state"] = status
    if resolved:
        vals["resolved"] = True
    if åtgärdsplan:
        vals["description"] = (alert.description or "") + "\n\n## Åtgärdsplan (AI)\n" + åtgärdsplan
    if vals:
        alert.write(vals)
    return f"Driftlarm {alert_id} uppdaterat: status={status or alert.diagnosis_state}, resolved={alert.resolved}"
